{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "status": "ready",
  "plan": {
    "title": "Next.js 16 Metadata API Basics",
    "interpretation": "I interpret 'Next.js 16 metadata API' as the App Router (app directory) metadata system: the generateMetadata export, the metadataBase option for relative metadata URLs, and canonical URL configuration via alternates.canonical. If you meant the Pages Router or a different Next.js version, tell me before we start.",
    "prerequisites": [
      "Basic familiarity with the Next.js App Router (app directory)",
      "Understanding of HTML <head> metadata such as title and description",
      "A Next.js project (or willingness to create one) using Next.js 16"
    ],
    "objectives": [
      {
        "id": "generateMetadata-rules",
        "text": "State the generateMetadata export rules, including that a route segment cannot export both metadata and generateMetadata."
      },
      {
        "id": "metadataBase",
        "text": "Explain how metadataBase sets a base URL for relative metadata URLs."
      },
      {
        "id": "canonical-url",
        "text": "Configure a canonical URL using alternates.canonical in generateMetadata."
      }
    ],
    "units": [
      {
        "id": "unit-1",
        "title": "generateMetadata export rules",
        "objectiveIds": ["generateMetadata-rules"]
      },
      {
        "id": "unit-2",
        "title": "metadataBase configuration",
        "objectiveIds": ["metadataBase"]
      },
      {
        "id": "unit-3",
        "title": "Canonical URL with alternates.canonical",
        "objectiveIds": ["canonical-url"]
      }
    ],
    "covers": "generateMetadata export rules, metadataBase base URL, and canonical URL via alternates.canonical in the Next.js 16 App Router.",
    "excludes": "The Pages Router (pages directory), static metadata object details beyond the export rule, dynamic metadata with loading.js, sitemaps, robots.txt, and server actions.",
    "estimatedMinutes": 15,
    "sourceExcerpts": []
  },
  "reason": null,
  "reasonCode": null
}

